const getSplitJobProgress = `-- name: GetSplitJobProgress :one
WITH target AS (
    SELECT COALESCE(t.split_of_job_id, t.id) AS root_id
    FROM production_jobs t
    WHERE t.id = $1
)
SELECT
    target.root_id,
    COALESCE(sum(pj.quantity), 0)::bigint AS total_quantity,
    COALESCE(sum(pj.quantity) FILTER (WHERE pj.status = 'completed'), 0)::bigint AS completed_quantity
FROM target
JOIN production_jobs pj ON COALESCE(pj.split_of_job_id, pj.id) = target.root_id
GROUP BY target.root_id
`

type GetSplitJobProgressRow struct {
	RootID            uuid.UUID
	TotalQuantity     int64
	CompletedQuantity int64
}

// Total ordered vs completed quantity across a split job's whole group (the
// root row plus every split_of_job_id fragment peeled off it) - "150 total /
// 72 printed / 78 remaining" derived on read, nothing stored. Safe to call
// with any job id in the group, root or fragment - root_id resolves to the
// job's own id when it was never split (every job is its own group of one).
func (q *Queries) GetSplitJobProgress(ctx context.Context, id uuid.UUID) (GetSplitJobProgressRow, error) {
	row := q.db.QueryRow(ctx, getSplitJobProgress, id)
	var i GetSplitJobProgressRow
	err := row.Scan(&i.RootID, &i.TotalQuantity, &i.CompletedQuantity)
	return i, err
}

const holdOrderPersonalisationForCustomer = `-- name: HoldOrderPersonalisationForCustomer :many
WITH target AS (
    SELECT pj.id, pj.batch_id
    FROM production_jobs pj
    WHERE pj.order_id = $1
      AND (pj.batch_id IS NULL
           OR pj.batch_id IN (SELECT b.id FROM batches b
                               WHERE b.status IN ('pending_approval', 'open')))
      AND pj.status IN ('pending', 'queued')
      AND pj.personalisation_status IN ('pending', 'validated', 'not_required')
      AND jsonb_array_length(coalesce(pj.personalisation_properties, '[]'::jsonb)) > 0
), held AS (
    UPDATE production_jobs j
    SET personalisation_status = 'awaiting_customer',
        -- Withdrawn as it is held, so no bed counts a job whose customer has
        -- not finished with it.
        batch_id               = NULL,
        updated_at             = now()
    FROM target t
    WHERE j.id = t.id
    RETURNING t.batch_id AS freed_batch_id
)
SELECT freed_batch_id FROM held
`

// Holds the REST of an order's personalised jobs while the customer's window
// is open.
//
// The renderer holds what it renders (confirmGeneratedPersonalisation), which
// covers the plank family and anything the registry describes. It cannot hold
// what it never renders - a Bone Tag, a DUOSNAP, a Couple's Date Plank - and
// those jobs were therefore shown on the customer's page with every field
// locked, because the edit path is guarded on awaiting_customer. A page of
// read-only boxes is not a check.
//
// Run when the link is actually SENT, not when the jobs are made. That is what
// keeps the invariant the hold depends on: every held job has a live link, so
// the expiry sweep and the confirm both find it and release it. Holding at
// creation would strand an order that never gets a link.
//
// A BED THAT HAS NOT STARTED IS NOT A COMMITMENT. This used to require
// batch_id IS NULL, on the reasoning that pulling a job back would disturb a
// plate that already counts it. True of a bed on a machine; false of one that
// is merely planned or approved.
//
// The cost of the stricter rule was the whole feature. On a floor that plans
// every few minutes, most orders are on a bed before the link is sent, so the
// hold skipped them, so SaveCustomerPersonalisation - which writes only to an
// awaiting_customer job - refused every edit with "this link is no longer
// available". The customer got a live page, a running clock, editable fields
// and a Save button that could not work. Measured on T3DPS-115768 and
// T3DPS-115801.
//
// pending_approval is a Draft the planner dissolves on its next run anyway.
// open is approved but not started: its plate can still be rebuilt, which is
// what the caller does with the beds this returns.
//
// in_progress AND completed ARE UNTOUCHABLE. That plate is on a printer or
// already made, and the order genuinely cannot change now. The customer's
// page says so rather than offering a field - see publicItem.
// ONE ROW PER HELD JOB, carrying the bed it came off if it was on one.
//
// Both facts are needed and they are not the same: the number of rows is how
// many items the customer can now correct, which is what decides whether a
// link is worth sending at all, while the non-null beds are the plates the
// caller has to rebuild. Returning only the beds would report "nothing held"
// for the ordinary case of an order that was not batched yet.
func (q *Queries) HoldOrderPersonalisationForCustomer(ctx context.Context, orderID *uuid.UUID) ([]*uuid.UUID, error) {
	rows, err := q.db.Query(ctx, holdOrderPersonalisationForCustomer, orderID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*uuid.UUID{}
	for rows.Next() {
		var freed_batch_id *uuid.UUID
		if err := rows.Scan(&freed_batch_id); err != nil {
			return nil, err
		}
		items = append(items, freed_batch_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

